import { type RequestHandler } from '@builder.io/qwik-city';

const DATASET = [
  { id: 1, name: 'Java' },
  { id: 2, name: 'JavaScript' },
  { id: 3, name: 'Jasmine' },
  { id: 4, name: 'Python' },
  { id: 5, name: 'Ruby' },
  { id: 6, name: 'Rust' },
  { id: 7, name: 'Go' },
  { id: 8, name: 'Kotlin' },
  { id: 9, name: 'Scala' },
  { id: 10, name: 'TypeScript' },
  { id: 11, name: 'C' },
  { id: 12, name: 'C++' },
  { id: 13, name: 'C#' },
  { id: 14, name: 'Haskell' },
  { id: 15, name: 'Elixir' },
  { id: 16, name: 'Erlang' },
  { id: 17, name: 'Perl' },
  { id: 18, name: 'PHP' },
  { id: 19, name: 'Swift' },
  { id: 20, name: 'Dart' }
];

export const onGet: RequestHandler = async (ev) => {
  const q = ev.query.get('q');
  const trimmed = q ? q.trim() : '';

  if (!q || trimmed.length < 2) {
    return ev.json(400, { error: 'query must be at least 2 characters' });
  }

  if (trimmed.length > 50) {
    return ev.json(400, { error: 'query must be at most 50 characters' });
  }

  const len = trimmed.length;
  const ms = Math.max(120, 1600 - (len - 2) * 500);

  // Apply artificial latency
  await new Promise((resolve) => setTimeout(resolve, ms));

  const lowerQ = trimmed.toLowerCase();
  if (lowerQ === 'boom') {
    return ev.json(500, { error: 'internal server error' });
  }

  const results = DATASET.filter((item) =>
    item.name.toLowerCase().includes(lowerQ)
  );

  // Ensure results are ordered by ascending id (they already are, but let's be explicit)
  results.sort((a, b) => a.id - b.id);

  return ev.json(200, {
    query: trimmed,
    count: results.length,
    results
  });
};

import { component$, useSignal, useTask$, useResource$, Resource } from '@builder.io/qwik';

interface SearchResultItem {
  id: number;
  name: string;
}

interface SearchResult {
  query: string;
  count: number;
  results: SearchResultItem[];
}

export default component$(() => {
  const inputValue = useSignal('');
  const debouncedQuery = useSignal('');

  // Debounce input value by 300ms
  useTask$(({ track, cleanup }) => {
    const value = track(inputValue);
    const id = setTimeout(() => {
      debouncedQuery.value = value;
    }, 300);
    cleanup(() => clearTimeout(id));
  });

  // Async resource tracking the debounced query
  const searchResource = useResource$<SearchResult | null>(async ({ track, cleanup }) => {
    const query = track(debouncedQuery);
    const trimmed = query.trim();

    if (trimmed.length < 2) {
      return null;
    }

    const abortController = new AbortController();
    cleanup(() => abortController.abort());

    const res = await fetch(`/api/search?q=${encodeURIComponent(trimmed)}`, {
      signal: abortController.signal,
    });

    if (!res.ok) {
      throw new Error('Search failed');
    }

    return res.json();
  });

  const showResource = debouncedQuery.value.trim().length >= 2;

  return (
    <div style={{ padding: '20px', fontFamily: 'sans-serif', maxWidth: '600px', margin: '0 auto' }}>
      <h1>Qwik Dev Search</h1>
      <div style={{ marginBottom: '20px' }}>
        <input
          type="text"
          data-testid="search-input"
          value={inputValue.value}
          onInput$={(ev, el) => {
            inputValue.value = el.value;
          }}
          placeholder="Type to search..."
          style={{
            width: '100%',
            padding: '10px',
            fontSize: '16px',
            borderRadius: '4px',
            border: '1px solid #ccc',
            boxSizing: 'border-box'
          }}
        />
      </div>

      {showResource && (
        <Resource
          value={searchResource}
          onPending={() => (
            <div data-testid="search-pending" style={{ color: '#666', fontStyle: 'italic' }}>
              Searching...
            </div>
          )}
          onRejected={() => (
            <div data-testid="search-error" style={{ color: 'red', fontWeight: 'bold' }}>
              Error: Search failed.
            </div>
          )}
          onResolved={(data) => {
            if (!data || data.results.length === 0) {
              return (
                <div data-testid="search-results" style={{ color: '#666' }}>
                  No results found.
                </div>
              );
            }
            return (
              <div
                data-testid="search-results"
                style={{
                  border: '1px solid #eee',
                  borderRadius: '4px',
                  backgroundColor: '#f9f9f9'
                }}
              >
                {data.results.map((result) => (
                  <div
                    key={result.id}
                    data-testid="search-result-item"
                    style={{
                      padding: '10px 15px',
                      borderBottom: '1px solid #eee'
                    }}
                  >
                    {result.name}
                  </div>
                ))}
              </div>
            );
          }}
        />
      )}
    </div>
  );
});
